//! 🧬️ Original action receivers are selected from the same closed authored mutation variants.
use super::*;
pub(super)fn expand(input:&DeriveInput)->syn::Result<Tokens>{let syn::Data::Enum(data)=&input.data else{return Err(error("native action receiving requires the actual mutation enum"))};let name=&input.ident;let mut arms=Vec::new();let mut entries=Vec::new();for variant in &data.variants{let syn::Fields::Unnamed(fields)=&variant.fields else{return Err(error("native action variants require exactly one leaf"))};if fields.unnamed.len()!=1{return Err(error("native action variants require exactly one leaf"))}let ty=&fields.unnamed[0].ty;let action=variant.ident.to_string();let factory=quote!(::semio_s_artifact_energy_model_native_mutations_singletons::action::NativeActionFactory::<Self>::of::<#ty>());arms.push(quote!(#action=>Some(#factory)));entries.push(quote!((#action,#factory)));}let(implementation,types,where_clause)=input.generics.split_for_impl();Ok(quote!{impl #implementation #name #types #where_clause{pub const ORIGINAL_ACTION_RECEIVERS:&'static[(&'static str,::semio_s_artifact_energy_model_native_mutations_singletons::action::NativeActionFactory<Self>)]=&[#(#entries,)*];pub fn original_action_receiver(action:&str)->Option<::semio_s_artifact_energy_model_native_mutations_singletons::action::NativeActionFactory<Self>>{match action{#(#arms,)*_=>None}}}})}
